      const itemElements = categoryLi.querySelectorAll('.lpItem')

      for (const itemEl of itemElements) {
        const item = parseHtmlItem(itemEl)
        if (item) {
          items.push(item)
        }
      }
    }
  } catch (error) {
    console.warn('Failed to parse HTML structure:', error)
  }

  return items
}

