CREATE TABLE listed_gear_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gear_id UUID NOT NULL REFERENCES gear_items(id) ON DELETE RESTRICT,
    list_category_id UUID REFERENCES list_categories(id) ON DELETE SET NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    worn BOOLEAN NOT NULL DEFAULT false,
