  }, [viewMode, weightUnit])

  const renderModals = useCallback(() => (
    <>
      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

