import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import { ImportGearForm } from './ImportGearForm'

// Mock useAuth hook
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id' }
  })
}))

// Mock supabase
vi.mock('@/lib/supabase', () => ({
  supabase: {
    from: () => ({
      select: () => ({
        eq: () => Promise.resolve({ data: [], error: null })
      })
    })
  }
}))

// Mock all child components to prevent complex interactions
vi.mock('./CsvImport', () => ({
  CsvImport: () => <div data-testid="csv-import">CSV Import</div>
}))

vi.mock('./UrlImport', () => ({
  UrlImport: () => <div data-testid="url-import">URL Import</div>
}))

vi.mock('./ImportPreview', () => ({
  ImportPreview: () => <div data-testid="import-preview">Import Preview</div>
}))

vi.mock('./ImportResults', () => ({
  ImportResults: () => <div data-testid="import-results">Import Results</div>
}))

describe('ImportGearForm', () => {
  const mockOnCancel = vi.fn()
  const mockOnImportComplete = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('should render with tabs', async () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    await waitFor(() => {
      expect(screen.getByText('Import Gear')).toBeInTheDocument()
    })

    expect(screen.getByText('CSV File')).toBeInTheDocument()
    expect(screen.getByText('LighterPack URL')).toBeInTheDocument()
  })

  it('should show CSV import by default', async () => {
    render(
      <ImportGearForm
        onCancel={mockOnCancel}
        onImportComplete={mockOnImportComplete}
      />
    )

    await waitFor(() => {
      expect(screen.getByTestId('csv-import')).toBeInTheDocument()
    })
  })
})

