const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
  // Match on item_type and label/description (case insensitive)
  const importItemType = importItem.item_type.toLowerCase().trim()
  const importLabel = (importItem.label || '').toLowerCase().trim()  // ParsedGearItem uses 'label'
  const existingItemType = existingItem.item_type.toLowerCase().trim()
  const existingDescription = (existingItem.description || '').toLowerCase().trim()  // GearItem uses 'description'

  return importItemType === existingItemType && importLabel === existingDescription
}

