import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview'
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('url')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: []
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        items={importState.items}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Import Gear</CardTitle>
        <CardDescription>
          Import your gear from LighterPack by URL or CSV file
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-6">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="csv" className="mt-6">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-6 pt-4 border-t">
          <Button variant="ghost" onClick={handleClose}>
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { CheckCircle, AlertCircle, Info, Package, X, Weight, Tag, ArrowLeft, Loader2 } from 'lucide-react'
import { StatTile } from '@/components/ui/stat-tile'
import { GearTable } from '@/components/gear/GearTable'
import { formatWeightForDisplay, formatWeightWithUnit } from '@/utils/weight'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'

interface ImportPreviewProps {
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors?: string[]
  warnings?: string[]
  metadata?: any
  onCancel: () => void
  className?: string
}

export function ImportPreview({
  items,
  newItems,
  duplicates,
  errors = [],
  metadata,
  onCancel,
  className
}: ImportPreviewProps) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [isImporting, setIsImporting] = useState(false)
  const [importError, setImportError] = useState<string | null>(null)
  const newItemsWeight = newItems.reduce((sum, item) => sum + item.weight_g, 0)
  const newCategories = new Set(newItems.map(item => item.item_type))

  const handleImport = async () => {
    if (!user) {
      setImportError('User not authenticated')
      return
    }

    setIsImporting(true)
    setImportError(null)

    try {
      const gearRepository = createGearRepository(user.id)

      // Convert newItems to the format expected by the repository  
      const itemsToCreate = newItems.map(item => ({
        item_type: item.item_type,
        description: item.description,
        brand: item.brand,
        model: item.model,
        consumable: item.consumable,
        price: item.price,
        weight_g: item.weight_g,
        weight_unit_display: item.weight_unit_display,
        notes: item.notes,
        image_url: item.image_url,
        url: item.url
      }))

      // Use createMany for bulk insert
      await gearRepository.createMany(itemsToCreate)

      // Redirect to gear closet
      navigate('/gear')
    } catch (error) {
      console.error('Failed to import items:', error)
      setImportError(error instanceof Error ? error.message : 'Unknown error occurred')
    } finally {
      setIsImporting(false)
    }
  }

  // Convert ParsedGearItem to GearItem format for GearTable
  const newItemsForTable: GearItem[] = newItems.map((item, index) => ({
    id: `preview-${index}`,
    user_id: '',
    item_type: item.item_type,
    description: item.description,
    brand: item.brand || null,
    model: item.model || null,
    consumable: item.consumable,
    price: item.price || null,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes || null,
    image_url: item.image_url || null,
    url: item.url || null,
    created_at: '',
    updated_at: ''
  }))

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <CheckCircle className="h-5 w-5 text-green-600" />
          Import Preview
        </CardTitle>
        <CardDescription>
          {metadata?.listName && (
            <span className="block font-medium mt-1">{metadata.listName}</span>
          )}
          {newItems.length > 0 ? (
            <>
              {newItems.length} new items will be imported
              {duplicates.length > 0 && (
                <span className="text-muted-foreground"> • {duplicates.length} duplicates skipped</span>
              )}
            </>
          ) : (
            "No new items to import (all items already exist)"
          )}
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* No New Items Special Case */}
        {newItems.length === 0 && duplicates.length > 0 && (
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">All items already exist in your gear library</div>
              <div className="text-sm">
                We found {duplicates.length} items from your import, but they all match items you already have.
                You can go back to import different data or close this dialog.
              </div>
            </AlertDescription>
          </Alert>
        )}

        {/* Errors */}
        {errors.length > 0 && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {errors.map((error, i) => (
                  <li key={i} className="text-sm">{error}</li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Summary Stats - Dashboard Style */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
          <StatTile
            title="New Items"
            value={newItems.length}
            description="items to import"
            icon={Package}
            iconColor="success"
          />
          <StatTile
            title="Duplicates Skipped"
            value={duplicates.length}
            description="already exist"
            icon={X}
            iconColor="warning"
          />
          <StatTile
            title="New Weight"
            value={formatWeightForDisplay(newItemsWeight)}
            description="total weight"
            icon={Weight}
            iconColor="info"
          />
          <StatTile
            title="Categories"
            value={newCategories.size}
            description="gear types"
            icon={Tag}
            iconColor="primary"
          />
        </div>

        {/* New Items Table */}
        {newItems.length > 0 && (
          <div className="space-y-3">
            <h4 className="font-medium">New Items to Import</h4>
            <div className="max-h-80 overflow-y-auto">
              <GearTable
                items={newItemsForTable}
                viewMode="normal"
                weightUnit="g" // Show in grams for now (could be made configurable)
                onEdit={() => {}} // No editing in preview
                onDelete={() => {}} // No deleting in preview
                showActions={false}
              />
            </div>
          </div>
        )}

        {/* Duplicates Preview */}
        {duplicates.length > 0 && (
          <div>
            <h4 className="font-medium mb-3 text-orange-600">Duplicate Items (will be skipped)</h4>
            <div className="space-y-2 max-h-32 overflow-y-auto">
              {duplicates.slice(0, 3).map((item, i) => (
                <div key={i} className="flex items-center justify-between p-2 bg-orange-50 border border-orange-200 rounded">
                  <div className="flex-1">
                    <div className="font-medium text-orange-800">{item.label}</div>
                    <div className="text-sm text-orange-600">
                      {item.item_type} • {formatWeightWithUnit(item.weight_g, item.weight_display_unit)}
                      {item.brand && ` • ${item.brand}`}
                    </div>
                  </div>
                  <span className="text-xs bg-orange-200 text-orange-800 px-2 py-1 rounded">Already exists</span>
                </div>
              ))}
              {duplicates.length > 3 && (
                <div className="text-center text-sm text-orange-600 py-2">
                  ... and {duplicates.length - 3} more duplicates
                </div>
              )}
            </div>
          </div>
        )}

        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-3 pt-4">
          {newItems.length > 0 ? (
            <>
              <Button onClick={handleImport} disabled={isImporting}>
                {isImporting ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import ${newItems.length} New Items`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting}>
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel}>
              Back to Import
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

