import type { GearItem, WeightUnit } from '@/types/database'

// Type for gear items during parsing - GearItem without database metadata
export type ParsedGearItem = Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>

// CSV row type
export interface CsvRow {
  [key: string]: string
}

export interface ParseResult<T> {
  success: boolean
  data: T[]
  errors: string[]
  warnings: string[]
  metadata?: any
}

export type GearParseResult = ParseResult<ParsedGearItem>

// Common validation functions
export function validateParsedGearItem(item: ParsedGearItem): string[] {
  const errors: string[] = []

  if (!item.description || item.description.length < 2) {
    errors.push('Description must be at least 2 characters')
  }

  if (item.weight_g <= 0) {
    errors.push('Weight must be greater than 0')
  }

  if (item.weight_g > 50000) { // 50kg limit
    errors.push('Weight seems unrealistically high (over 50kg)')
  }

  if (!item.item_type || item.item_type.trim().length === 0) {
    errors.push('Item type is required')
  }

  return errors
}

// Helper to convert ParsedGearItem to GearItem creation data
export function toGearItemData(item: ParsedGearItem): Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'> {
  return {
    description: item.description,
    item_type: item.item_type,
    brand: item.brand,
    model: item.model,
    consumable: item.consumable,
    price: item.price,
    weight_g: item.weight_g,
    weight_unit_display: item.weight_unit_display,
    notes: item.notes,
    image_url: item.image_url,
    url: item.url
  }
}

// Weight parsing utilities
export interface WeightParseResult {
  grams: number
  unit: WeightUnit
}

export function parseWeightFromText(text: string): WeightParseResult {
  const cleaned = text.toLowerCase().replace(/[^\d.,ozlbkg\s]/g, '').trim()

  // Handle combined lb + oz format (e.g., "1 lb 5 oz")
  if (cleaned.includes('lb') && cleaned.includes('oz')) {
    const lbOzMatch = cleaned.match(/(\d+\.?\d*)\s*lb\s*(\d+\.?\d*)\s*oz/)
    if (lbOzMatch) {
      const lbs = parseFloat(lbOzMatch[1])
      const ozs = parseFloat(lbOzMatch[2])
      const grams = Math.round((lbs * 453.592) + (ozs * 28.3495))
      return { grams, unit: 'oz' } // Display in oz since it has oz precision
    }
  }

  // Single unit parsing
  const patterns = [
    { regex: /(\d+\.?\d*)\s*oz/, unit: 'oz' as WeightUnit, factor: 28.3495 },
    { regex: /(\d+\.?\d*)\s*lb/, unit: 'lb' as WeightUnit, factor: 453.592 },
    { regex: /(\d+\.?\d*)\s*kg/, unit: 'kg' as WeightUnit, factor: 1000 },
    { regex: /(\d+\.?\d*)\s*g/, unit: 'g' as WeightUnit, factor: 1 },
  ]

  for (const pattern of patterns) {
    const match = cleaned.match(pattern.regex)
    if (match) {
      const value = parseFloat(match[1])
      const grams = Math.round(value * pattern.factor)
      return { grams, unit: pattern.unit }
    }
  }

  // Fallback: try to parse as plain number (assume grams)
  const numMatch = cleaned.match(/(\d+\.?\d*)/)
  if (numMatch) {
    const value = parseFloat(numMatch[1])
    return { grams: Math.round(value), unit: 'g' }
  }

  throw new Error(`Could not parse weight from: ${text}`)
}

// Boolean parsing utility
export function parseBoolean(value: string | undefined): boolean {
  if (!value) return false
  const lower = value.toLowerCase().trim()
  return ['true', 'yes', '1', 'on', 'checked', 'x'].includes(lower)
}

// Common column mapping type
export interface ColumnMap {
  [field: string]: number | undefined
}

import { useState, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Upload, FileText, Info } from 'lucide-react'
import { parseCsv } from '@/utils/parser/csv'
import { validateParsedGearItem, checkForDuplicates } from '@/utils/parser'
import type { ParsedGearItem } from '@/utils/parser'

interface CsvImportProps {
  onImportData: (items: ParsedGearItem[], errors?: string[], warnings?: string[]) => void
}

export function CsvImport({ onImportData }: CsvImportProps) {
  const [isDragOver, setIsDragOver] = useState(false)
  const [isProcessing, setIsProcessing] = useState(false)
  const [fileName, setFileName] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (file: File) => {
    if (!file.name.toLowerCase().endsWith('.csv')) {
      onImportData([], ['Please select a CSV file (.csv extension)'])
      return
    }

    setFileName(file.name)
    setIsProcessing(true)

    const reader = new FileReader()
    reader.onload = (e) => {
      const csvContent = e.target?.result as string
      processCsvContent(csvContent)
    }
    reader.onerror = () => {
      onImportData([], ['Failed to read file. Please try again.'])
      setIsProcessing(false)
    }
    reader.readAsText(file)
  }

  const processCsvContent = (csvContent: string) => {
    try {
      // Parse CSV
      const parseResult = parseCsv(csvContent)

      if (!parseResult.success) {
        onImportData([], parseResult.errors, parseResult.warnings)
        setIsProcessing(false)
        return
      }

      // Validate items
      const { valid, invalid } = validateGearItems(parseResult.data)

      const errors: string[] = [...parseResult.errors]
      const warnings: string[] = [...parseResult.warnings]

      // Add validation errors
      invalid.forEach(({ item, errors: itemErrors }) => {
        errors.push(`"${item.name}": ${itemErrors.join(', ')}`)
      })

      // Add warnings for any issues
      if (invalid.length > 0) {
        warnings.push(`${invalid.length} items had validation errors and were skipped`)
      }

      // Check for duplicates in valid items
      const { unique, duplicates, warnings: duplicateWarnings } = checkForDuplicates(valid)
      warnings.push(...duplicateWarnings)

      if (duplicates.length > 0) {
        duplicates.forEach(({ item }) => {
          warnings.push(`Removed duplicate: "${item.name}" (${item.weight_grams}g)`)
        })
      }

      if (unique.length > 0) {
        warnings.push(`Successfully parsed ${unique.length} unique items`)
      }

      onImportData(unique, errors, warnings)

    } catch (error) {
      onImportData([], [`Unexpected error: ${error instanceof Error ? error.message : 'Unknown error'}`])
    } finally {
      setIsProcessing(false)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)

    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleClickUpload = () => {
    fileInputRef.current?.click()
  }

  return (
    <div className="space-y-4">
      {/* Instructions */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">How to export from LighterPack:</div>
          <ol className="list-decimal list-inside space-y-1 text-sm">
            <li>Go to your LighterPack list</li>
            <li>Click the "Export" button</li>
            <li>Select "CSV" format</li>
            <li>Upload the downloaded file below</li>
          </ol>
        </AlertDescription>
      </Alert>

      {/* File Upload Area */}
      <div
        className={`
          border-2 border-dashed rounded-lg p-8 text-center transition-colors
          ${isDragOver ? 'border-primary bg-primary/5' : 'border-muted-foreground/25'}
          ${isProcessing ? 'opacity-50 pointer-events-none' : 'cursor-pointer hover:border-primary hover:bg-primary/5'}
        `}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClickUpload}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv"
          onChange={handleFileInputChange}
          className="hidden"
          disabled={isProcessing}
        />

        <div className="space-y-3">
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary mx-auto" />
              <div className="text-sm font-medium">Processing {fileName}...</div>
            </>
          ) : (
            <>
              <Upload className="h-10 w-10 text-muted-foreground mx-auto" />
              <div>
                <div className="font-medium">Drop your CSV file here</div>
                <div className="text-sm text-muted-foreground mt-1">
                  or click to browse files
                </div>
              </div>
              <div className="text-xs text-muted-foreground">
                Supports LighterPack CSV exports (.csv files up to 10MB)
              </div>
            </>
          )}
        </div>
      </div>

      {/* Manual Upload Button */}
      <div className="text-center">
        <Button
          variant="outline"
          onClick={handleClickUpload}
          disabled={isProcessing}
          className="w-full sm:w-auto"
        >
          <FileText className="h-4 w-4 mr-2" />
          Choose CSV File
        </Button>
      </div>

      {/* CSV Format Info */}
      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <div className="font-medium mb-2">Expected CSV format:</div>
          <div className="text-sm space-y-1">
            <div><strong>Required columns:</strong> Name, Weight</div>
            <div><strong>Optional columns:</strong> Brand, Category, Quantity, Worn, Consumable, Price, Description, Notes</div>
            <div className="text-muted-foreground">Column names are flexible - we'll automatically detect common variations.</div>
          </div>
        </AlertDescription>
      </Alert>
    </div>
  )
}

