import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen } from '@testing-library/react'
import { ImportPreview } from './ImportPreview'
import type { ParsedGearItem } from '@/utils/parser'

// Mock useAuth hook
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id' }
  })
}))

// Mock supabase
vi.mock('@/lib/supabase', () => {
  const mockChain = {
    insert: () => Promise.resolve({ data: [], error: null })
  }

  return {
    supabase: {
      from: () => mockChain
    }
  }
}))

// Mock useNavigate
vi.mock('react-router-dom', () => ({
  useNavigate: () => vi.fn()
}))

describe('ImportPreview', () => {
  const mockOnCancel = vi.fn()

  const sampleItems: ParsedGearItem[] = [
    {
      description: 'Test Backpack',
      brand: 'Test Brand',
      model: null,
      weight_g: 1500,
      weight_unit_display: 'g',
      item_type: 'Shelter',
      consumable: false,
      price: null,
      notes: null,
      image_url: null,
      url: null
    },
    {
      description: 'Test Jacket',
      brand: 'Another Brand',
      model: null,
      weight_g: 400,
      weight_unit_display: 'g',
      item_type: 'Clothing',
      consumable: false,
      price: null,
      notes: null,
      image_url: null,
      url: null
    }
  ]

  beforeEach(() => {
    vi.clearAllMocks()
  })

  describe('Basic Rendering', () => {
    it('should render import preview with items', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={sampleItems}
          duplicates={[]}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('Import Preview')).toBeInTheDocument()
      expect(screen.getByText('1 new items will be imported')).toBeInTheDocument()
    })

    it('should display weight in grams when under 1000g', () => {
      const lightItems: ParsedGearItem[] = [
        {
          description: 'Light Item',
          brand: 'Test Brand',
          model: null,
          weight_g: 250,
          weight_unit_display: 'g',
          item_type: 'Other',
          consumable: false,
          price: null,
          notes: null,
          image_url: null,
          url: null
        }
      ]

      render(
        <ImportPreview
          items={lightItems}
          newItems={lightItems}
          duplicates={[]}
          onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('250g')).toBeInTheDocument()
    })
  })

  describe('No New Items Case', () => {
    it('should show special message when no new items but has duplicates', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={[]}
          duplicates={sampleItems}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('All items already exist in your gear library')).toBeInTheDocument()
      expect(screen.getByText(/We found 2 items from your import, but they all match items you already have/)).toBeInTheDocument()
    })

    it('should show "Back to Import" button when no new items', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={[]}
          duplicates={sampleItems}
                    onCancel={mockOnCancel}
        />
      )

      const backButton = screen.getByRole('button', { name: /Back to Import/i })
      expect(backButton).toBeInTheDocument()
      expect(screen.queryByRole('button', { name: /Import.*Items/i })).not.toBeInTheDocument()
    })

    it('should show correct description when no new items', () => {
      render(
        <ImportPreview
          items={sampleItems}
          newItems={[]}
          duplicates={sampleItems}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('No new items to import (all items already exist)')).toBeInTheDocument()
    })
  })

  describe('Mixed New Items and Duplicates', () => {
    it('should show correct counts for new items vs duplicates', () => {
      const newItems = [sampleItems[0]] // 1 new item
      const duplicates = [sampleItems[1]] // 1 duplicate

      render(
        <ImportPreview
          items={sampleItems}
          newItems={newItems}
          duplicates={duplicates}
                    onCancel={mockOnCancel}
        />
      )

      // Check statistics
      expect(screen.getByText('1', { selector: '.text-green-600' })).toBeInTheDocument() // New items count
      expect(screen.getByText('1', { selector: '.text-orange-600' })).toBeInTheDocument() // Duplicates count

      // Check description
      expect(screen.getByText('1 new items will be imported')).toBeInTheDocument()
      expect(screen.getByText(/1 duplicates skipped/)).toBeInTheDocument()
    })

    it('should show import button with correct count for new items', () => {
      const newItems = [sampleItems[0]]
      const duplicates = [sampleItems[1]]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={newItems}
          duplicates={duplicates}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByRole('button', { name: 'Import 1 New Items' })).toBeInTheDocument()
    })
  })

  describe('Visual Organization', () => {
    it('should show new items with green styling', () => {
      const newItems = [sampleItems[0]]
      const duplicates = [sampleItems[1]]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={newItems}
          duplicates={duplicates}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('New Items to Import (first 5)')).toBeInTheDocument()
      // New items should have green border class
      const newItemContainer = screen.getByText('Test Backpack').closest('.border-green-200')
      expect(newItemContainer).toBeInTheDocument()
    })

    it('should show duplicate items with orange styling', () => {
      const newItems = [sampleItems[0]]
      const duplicates = [sampleItems[1]]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={newItems}
          duplicates={duplicates}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('Duplicate Items (will be skipped)')).toBeInTheDocument()
      // Duplicate items should have orange background
      const duplicateContainer = screen.getByText('Test Jacket').closest('.bg-orange-50')
      expect(duplicateContainer).toBeInTheDocument()
      expect(screen.getByText('Already exists')).toBeInTheDocument()
    })
  })

  describe('Clean Warnings Display', () => {
    it('should show summary warnings without ugly lists', () => {
      const warnings = [
        '1 items skipped as duplicates (already exist in your gear library)',
        '1 new items ready to import'
      ]

      render(
        <ImportPreview
          items={sampleItems}
          newItems={[sampleItems[0]]}
          duplicates={[sampleItems[1]]}
          warnings={warnings}
                    onCancel={mockOnCancel}
        />
      )

      expect(screen.getByText('1 items skipped as duplicates (already exist in your gear library)')).toBeInTheDocument()
      expect(screen.getByText('1 new items ready to import')).toBeInTheDocument()

      // Should NOT show individual item listings like "• Skipped: Item Name"
      expect(screen.queryByText(/• Skipped:/)).not.toBeInTheDocument()
    })
  })
})

