import { describe, it, expect } from 'vitest'
import type { ParsedGearItem } from '@/utils/parser'
import type { GearItem } from '@/types/database'

// Extract the duplicate checking logic for testing
function isDuplicate(importItem: ParsedGearItem, existingItem: GearItem): boolean {
  // Match on name and brand (case insensitive)
  const importName = importItem.name.toLowerCase().trim()
  const importBrand = (importItem.brand || '').toLowerCase().trim()
  const existingName = existingItem.name.toLowerCase().trim()
  const existingBrand = (existingItem.brand || '').toLowerCase().trim()

  return importName === existingName && importBrand === existingBrand
}

function deduplicateItems(importItems: ParsedGearItem[], existingItems: GearItem[]) {
  const newItems: ParsedGearItem[] = []
  const duplicates: ParsedGearItem[] = []

  importItems.forEach(importItem => {
    const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
    if (isDuplicateItem) {
      duplicates.push(importItem)
    } else {
      newItems.push(importItem)
    }
  })

  return { newItems, duplicates }
}

describe('Gear Import Deduplication', () => {
  const existingItems: GearItem[] = [
    {
      id: 'existing-1',
      user_id: 'test-user',
      name: 'Osprey Atmos 65',
      brand: 'Osprey',
      weight_grams: 2200,
      category: 'Backpack',
      quantity: 1,
      worn: false,
      consumable: false,
      created_at: new Date().toISOString(),
      notes: null,
      price: null,
      description: null,
      image_url: null
    },
    {
      id: 'existing-2', 
      user_id: 'test-user',
      name: 'Patagonia Down Sweater',
      brand: null, // No brand
      weight_grams: 400,
      category: 'Clothing',
      quantity: 1,
      worn: false,
      consumable: false,
      created_at: new Date().toISOString(),
      notes: null,
      price: null,
      description: null,
      image_url: null
    }
  ]

  it('should identify exact duplicates (same name and brand)', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: 'Osprey Atmos 65',
        brand: 'Osprey',
        weight_grams: 2200,
        category: 'Backpack',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(0)
    expect(duplicates).toHaveLength(1)
    expect(duplicates[0].name).toBe('Osprey Atmos 65')
  })

  it('should identify case-insensitive duplicates', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: 'OSPREY ATMOS 65',
        brand: 'osprey',
        weight_grams: 2200,
        category: 'Backpack',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(0)
    expect(duplicates).toHaveLength(1)
  })

  it('should handle items with no brand', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: 'Patagonia Down Sweater',
        brand: null,
        weight_grams: 400,
        category: 'Clothing',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(0)
    expect(duplicates).toHaveLength(1)
  })

  it('should treat different brands as unique items', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: 'Down Sweater',
        brand: 'Arc\'teryx', // Different brand
        weight_grams: 380,
        category: 'Clothing',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(1)
    expect(duplicates).toHaveLength(0)
  })

  it('should treat different names as unique items', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: 'Osprey Exos 58', // Different name
        brand: 'Osprey',
        weight_grams: 1200,
        category: 'Backpack',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(1)
    expect(duplicates).toHaveLength(0)
  })

  it('should handle mixed new and duplicate items', () => {
    const importItems: ParsedGearItem[] = [
      // Duplicate
      {
        name: 'Osprey Atmos 65',
        brand: 'Osprey',
        weight_grams: 2200,
        category: 'Backpack',
        quantity: 1,
        worn: false,
        consumable: false
      },
      // New item
      {
        name: 'Thermarest NeoAir XLite',
        brand: 'Thermarest',
        weight_grams: 350,
        category: 'Sleep System',
        quantity: 1,
        worn: false,
        consumable: false
      },
      // Another duplicate
      {
        name: 'patagonia down sweater', // Case insensitive
        brand: '', // Empty brand (should match null brand)
        weight_grams: 400,
        category: 'Clothing',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(1)
    expect(newItems[0].name).toBe('Thermarest NeoAir XLite')

    expect(duplicates).toHaveLength(2)
    expect(duplicates.map(d => d.name)).toContain('Osprey Atmos 65')
    expect(duplicates.map(d => d.name)).toContain('patagonia down sweater')
  })

  it('should handle whitespace in names and brands', () => {
    const importItems: ParsedGearItem[] = [
      {
        name: '  Osprey Atmos 65  ', // Extra whitespace
        brand: '  Osprey  ',
        weight_grams: 2200,
        category: 'Backpack',
        quantity: 1,
        worn: false,
        consumable: false
      }
    ]

    const { newItems, duplicates } = deduplicateItems(importItems, existingItems)

    expect(newItems).toHaveLength(0)
    expect(duplicates).toHaveLength(1)
  })
})

