import { describe, it, expect } from 'vitest'
import { parseCsv } from './csv'
import { validateParsedGearItem } from './index'

describe('CSV Parser', () => {
  describe('parseCsv', () => {
    it('should parse basic CSV with required fields', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter
Sleeping Bag,800g,Sleep System`

      const result = parseCsv(csv)

      // Debug output
      if (!result.success) {
        console.log('Parse result:', result)
      }

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.errors).toHaveLength(0)

      expect(result.data[0]).toMatchObject({
        label: 'Tent',
        weight_g: 1200,
        item_type: 'Shelter',
        consumable: false
      })
    })

    it('should handle different weight units', () => {
      const csv = `name,weight
Item1,2.5oz
Item2,1200g
Item3,1.5 oz`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].weight_g).toBeCloseTo(71, 0) // 2.5oz ≈ 71g
      expect(result.data[1].weight_g).toBe(1200)
      expect(result.data[2].weight_g).toBeCloseTo(43, 0) // 1.5oz ≈ 43g
    })

    it('should handle quoted fields with commas', () => {
      const csv = `name,weight,description
"Tent, 2-person",1200g,"Lightweight, waterproof"
Stove,150g,"Compact, efficient"`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].label).toBe('Tent, 2-person')
      expect(result.data[0].description).toBe('Lightweight, waterproof')
    })

    it('should handle flexible column naming', () => {
      const csv = `Item Name,Weight (g),Gear Type,Qty,Brand
Ultralight Tent,1000,Shelter,1,Zpacks
Water Bottle,100,Water,2,Nalgene`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.data[0]).toMatchObject({
        label: 'Ultralight Tent',
        weight_g: 1000,
        item_type: 'Shelter',
        brand: 'Zpacks'
      })
    })

    it('should handle boolean fields', () => {
      const csv = `name,weight,worn,consumable
Base Layer,200g,true,false
Energy Bar,50g,no,yes`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].consumable).toBe(false)
      expect(result.data[1].consumable).toBe(true)
    })

    it('should handle price parsing', () => {
      const csv = `name,weight,price
Tent,1200g,$299.99
Stove,150g,89.50`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].price).toBe(299.99)
      expect(result.data[1].price).toBe(89.50)
    })

    it('should fail with missing required columns', () => {
      const csv = `description,color
Nice tent,Blue`

      const result = parseCsv(csv)

      expect(result.success).toBe(false)
      expect(result.errors).toContain('No label/item column found. Required columns: label, weight')
    })

    it('should handle empty rows and malformed data gracefully', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter

,invalid,
Good Item,500g,Other`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2) // Should skip empty/invalid rows
      expect(result.data[0].label).toBe('Tent')
      expect(result.data[1].label).toBe('Good Item')
    })

    it('should provide detailed error messages for invalid rows', () => {
      const csv = `name,weight
,200g
ValidItem,invalid_weight`

      const result = parseCsv(csv)

      expect(result.errors.length).toBeGreaterThan(0)
      expect(result.errors.some(e => e.includes('Item label is required'))).toBe(true)
    })

    it('should intelligently detect when description is used for categories', () => {
      const csv = `name,weight,description
Tent,1200g,shelter
Sleeping Bag,800g,sleep
Stove,200g,cook`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(3)
      expect(result.data[0].item_type).toBe('shelter')
      expect(result.data[1].item_type).toBe('sleep')
      expect(result.data[2].item_type).toBe('cook')
    })

    it('should extract brand information from descriptions', () => {
      const csv = `name,weight,description
Ultralight Tent,1000g,zpacks duplex ultralight
Water Filter,50g,sawyer mini portable
Headlamp,80g,petzl actik rechargeable`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Zpacks')
      expect(result.data[1].brand).toBe('Sawyer')
      expect(result.data[2].brand).toBe('Petzl')
    })

    it('should handle mixed usage patterns intelligently', () => {
      const csv = `name,weight,description,notes
Base Layer,200g,patagonia merino,warm and comfortable
Sleeping Pad,400g,sleep,r-value 4.5
Cook Pot,150g,cooking gear,titanium construction`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Patagonia')
      expect(result.data[0].notes).toBe('warm and comfortable')
      expect(result.data[1].item_type).toBe('Sleep System') // Intelligent detection converts 'sleep' to proper category
      expect(result.data[1].notes).toBe('r-value 4.5')
      expect(result.data[2].item_type).toBe('Cooking') // Intelligent detection converts 'cooking gear' to proper category
      expect(result.data[2].notes).toBe('titanium construction')
    })
  })

  describe('validateParsedGearItem', () => {
    it('should validate correct items', () => {
      const items = [
        {
          label: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false,
          price: 25.99
        }
      ]

      const result = validateParsedGearItem(items)

      expect(result.valid).toHaveLength(2)
      expect(result.invalid).toHaveLength(0)
    })

    it('should catch validation errors', () => {
      const items = [
        {
          label: 'A', // Too short
          weight_g: 0, // Invalid weight
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Heavy Item',
          weight_g: 100000, // Too heavy
          item_type: 'Other',
          consumable: false,
          price: -10 // Negative price
        }
      ]

      const result = validateParsedGearItem(items)

      expect(result.valid).toHaveLength(0)
      expect(result.invalid).toHaveLength(2)

      // Check specific validation errors
      const firstItemErrors = result.invalid[0].errors
      expect(firstItemErrors).toContain('Label must be at least 2 characters')
      expect(firstItemErrors).toContain('Weight must be greater than 0')

      const secondItemErrors = result.invalid[1].errors
      expect(secondItemErrors).toContain('Weight seems unusually high (>50kg)')
      expect(secondItemErrors).toContain('Price cannot be negative')
    })

    it('should handle edge cases', () => {
      const items = [
        {
          label: 'Valid Item',
          weight_g: 100,
          item_type: 'Other',
          consumable: false,
          price: 0 // Zero price should be valid
        }
      ]

      const result = validateParsedGearItem(items)

      expect(result.valid).toHaveLength(1)
      expect(result.invalid).toHaveLength(0)
    })
  })

  describe('checkForDuplicates', () => {
    it('should identify exact duplicates', () => {
      const items = [
        {
          label: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Tent', // Exact duplicate
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Sleeping Bag',
          weight_g: 800,
          item_type: 'Sleep',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(1)
      expect(result.warnings).toContain('Found 1 potential duplicate (similar label/weight/brand)')
      expect(result.duplicates[0].duplicateOf).toBe(0) // Duplicate of first item
    })

    it('should identify duplicates with similar weights', () => {
      const items = [
        {
          label: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          label: 'Water Bottle', // Similar weight (within 5g tolerance)
          weight_g: 153,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should not consider items with different weights as duplicates', () => {
      const items = [
        {
          label: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          label: 'Water Bottle', // Different weight (>5g difference)
          weight_g: 200,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(0)
    })

    it('should consider case-insensitive name matching', () => {
      const items = [
        {
          label: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'TENT', // Same label, different case
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle brand matching for duplicates', () => {
      const items = [
        {
          label: 'Tent',
          brand: 'Zpacks',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Tent',
          brand: 'MSR', // Different brand
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Tent',
          brand: 'Zpacks', // Same brand - should be duplicate
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2) // Zpacks and MSR tents
      expect(result.duplicates).toHaveLength(1) // Second Zpacks tent
    })

    it('should handle items without brands', () => {
      const items = [
        {
          label: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          label: 'Water Bottle', // No brand on either - should be duplicate
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle multiple duplicates correctly', () => {
      const items = [
        {
          label: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        },
        {
          label: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        },
        {
          label: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(2)
      expect(result.warnings).toContain('Found 2 potential duplicates (similar label/weight/brand)')
    })

    it('should return no duplicates for unique items', () => {
      const items = [
        {
          label: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          label: 'Sleeping Bag',
          weight_g: 800,
