for (let j = 0; j < unique.length; j++) {
  const existingItem = unique[j]

  // Check if descriptions match (case-insensitive)
  const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

  // Check if weights are similar (within 5g)
  const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

  // Check if brands match (case-insensitive, treating null/undefined as empty)
  const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

  if (descriptionsMatch && weightsMatch && brandsMatch) {
    duplicates.push({ item: currentItem, duplicateOf: j })
    isDuplicate = true
    break
  }
}
